Here's the full setup â€” copy these directly (no need for the sandbox, just paste into your VM).

### 1. Poll scripts

```bash
mkdir -p ~/.config/eww/scripts
```

**`~/.config/eww/scripts/cpu.sh`**
```bash
#!/bin/bash
top -bn1 | grep "Cpu(s)" | awk '{print 100 - $8}' | cut -d. -f1
```

**`~/.config/eww/scripts/mem.sh`**
```bash
#!/bin/bash
free | awk '/Mem/{printf "%.0f", $3/$2 * 100}'
```

**`~/.config/eww/scripts/bat.sh`**
```bash
#!/bin/bash
cat /sys/class/power_supply/BAT0/capacity 2>/dev/null || echo "N/A"
```

Make them executable:
```bash
chmod +x ~/.config/eww/scripts/*.sh
```

### 2. `~/.config/eww/eww.yuck`

```lisp
(defpoll cpu :interval "2s" "bash ~/.config/eww/scripts/cpu.sh")
(defpoll mem :interval "2s" "bash ~/.config/eww/scripts/mem.sh")
(defpoll bat :interval "10s" "bash ~/.config/eww/scripts/bat.sh")
(defpoll clock :interval "1s" "date '+%H:%M'")
(defpoll date :interval "60s" "date '+%a, %d %b'")

(defwidget sysmonitor []
  (box :class "sys-box" :orientation "v" :space-evenly false
    (label :class "sys-title" :text "// SYS::MONITOR")
    (box :class "sys-row" :orientation "h"
      (label :text "CPU")
      (label :class "sys-val" :text "${cpu}%"))
    (box :class "sys-row" :orientation "h"
      (label :text "MEM")
      (label :class "sys-val" :text "${mem}%"))
    (box :class "sys-row" :orientation "h"
      (label :text "BAT")
      (label :class "sys-val" :text "${bat}%"))))

(defwidget clockwidget []
  (box :class "clock-box" :orientation "v" :space-evenly false
    (label :class "clock-time" :text clock)
    (label :class "clock-date" :text date)))

(defwidget launcher-item [icon name cmd]
  (button :class "launcher-item" :onclick cmd
    (box :orientation "h" :space-evenly false
      (label :class "launcher-icon" :text icon)
      (label :class "launcher-name" :text name))))

(defwidget sidebar []
  (box :class "sidebar" :orientation "v" :space-evenly false
    (launcher-item :icon "" :name "terminal" :cmd "foot &")
    (launcher-item :icon "" :name "app launcher" :cmd "rofi -show drun &")
    (launcher-item :icon "" :name "browser" :cmd "qutebrowser &")
    (launcher-item :icon "" :name "neovim" :cmd "foot nvim &")
    (launcher-item :icon "" :name "select wall" :cmd "feh --bg-fill ~/Pictures/wall.jpg &")))

(defwindow sidebar-window
  :monitor 0
  :geometry (geometry :x "20px" :y "60px" :width "220px" :height "300px" :anchor "left center")
  :stacking "fg"
  (sidebar))

(defwindow sysmonitor-window
  :monitor 0
  :geometry (geometry :x "20px" :y "20px" :width "220px" :height "120px" :anchor "top right")
  :stacking "fg"
  (sysmonitor))

(defwindow clock-window
  :monitor 0
  :geometry (geometry :x "20px" :y "20px" :width "150px" :height "80px" :anchor "bottom right")
  :stacking "fg"
  (clockwidget))
```

### 3. `~/.config/eww/eww.scss`

```scss
* {
  font-family: "JetBrainsMono Nerd Font", monospace;
}

.sidebar {
  background-color: rgba(60, 10, 15, 0.85);
  border-radius: 12px;
  padding: 10px;
}

.launcher-item {
  background-color: transparent;
  color: #f2d9d9;
  padding: 8px;
  margin: 4px 0px;
  border-radius: 8px;
  border: none;
}

.launcher-item:hover {
  background-color: rgba(150, 40, 40, 0.5);
}

.launcher-icon {
  margin-right: 8px;
  color: #d97a7a;
}

.sys-box {
  background-color: rgba(40, 8, 10, 0.85);
  border-radius: 10px;
  padding: 10px;
  color: #f2d9d9;
}

.sys-title {
  color: #d97a7a;
  font-size: 11px;
  margin-bottom: 6px;
}

.sys-row {
  margin: 2px 0px;
}

